namespace sv_a4d5940d68c947ddb9efef3b0b177033.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Shipments = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment
        {
            TrackingNumber = "PKG-001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 11, 17, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "New York, NY", Timestamp = new DateTimeOffset(2026, 7, 6, 9, 0, 0, TimeSpan.FromHours(-5)) },
                new StatusUpdate { Description = "Departed facility", Location = "New York, NY", Timestamp = new DateTimeOffset(2026, 7, 6, 14, 30, 0, TimeSpan.FromHours(-5)) },
                new StatusUpdate { Description = "Arrived at sorting center", Location = "Chicago, IL", Timestamp = new DateTimeOffset(2026, 7, 7, 22, 15, 0, TimeSpan.FromHours(-6)) },
                new StatusUpdate { Description = "In transit to destination", Location = "Chicago, IL", Timestamp = new DateTimeOffset(2026, 7, 8, 6, 0, 0, TimeSpan.FromHours(-6)) },
            ]
        },
        ["PKG-002"] = new Shipment
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 7, 12, 0, 0, TimeSpan.FromHours(-8)),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Seattle, WA", Timestamp = new DateTimeOffset(2026, 7, 4, 10, 0, 0, TimeSpan.FromHours(-8)) },
                new StatusUpdate { Description = "In transit", Location = "Portland, OR", Timestamp = new DateTimeOffset(2026, 7, 5, 8, 45, 0, TimeSpan.FromHours(-8)) },
                new StatusUpdate { Description = "Out for delivery", Location = "San Francisco, CA", Timestamp = new DateTimeOffset(2026, 7, 7, 7, 30, 0, TimeSpan.FromHours(-8)) },
                new StatusUpdate { Description = "Delivered", Location = "San Francisco, CA", Timestamp = new DateTimeOffset(2026, 7, 7, 11, 22, 0, TimeSpan.FromHours(-8)) },
            ]
        },
        ["PKG-003"] = new Shipment
        {
            TrackingNumber = "PKG-003",
            Status = "Processing",
            Location = "Dallas, TX",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 14, 18, 0, 0, TimeSpan.FromHours(-6)),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Label created", Location = "Dallas, TX", Timestamp = new DateTimeOffset(2026, 7, 8, 15, 0, 0, TimeSpan.FromHours(-6)) },
                new StatusUpdate { Description = "Awaiting pickup", Location = "Dallas, TX", Timestamp = new DateTimeOffset(2026, 7, 8, 15, 5, 0, TimeSpan.FromHours(-6)) },
            ]
        }
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        Shipments.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

