using sv_a4d5940d68c947ddb9efef3b0b177033.Client.Models;

namespace sv_a4d5940d68c947ddb9efef3b0b177033.Client.Services;

public class ShipmentHttpService(HttpClient httpClient) : IShipmentService
{
